package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(),
                entity.getLoanedAt(), entity.getDueAt(), entity.getReturnedAt(),
                toDomainCreditCheck(entity.getCreditCheck()));
    }

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), toEmbeddable(loan.getCreditCheck()));
    }

    private CreditCheck toDomainCreditCheck(CreditCheckEmbeddable embeddable) {
        if (embeddable == null) {
            return null;
        }
        List<String> reasonCodes = embeddable.getReasonCodes().isEmpty()
                ? List.of()
                : Arrays.asList(embeddable.getReasonCodes().split(","));
        return new CreditCheck(embeddable.isApproved(), embeddable.getScore(), embeddable.getCheckedAt(),
                reasonCodes, embeddable.getProviderName(), embeddable.getProviderVersion());
    }

    private CreditCheckEmbeddable toEmbeddable(CreditCheck creditCheck) {
        if (creditCheck == null) {
            return null;
        }
        return new CreditCheckEmbeddable(creditCheck.approved(), creditCheck.score(), creditCheck.checkedAt(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.providerName(),
                creditCheck.providerVersion());
    }
}

