package com.example.lending;

import com.example.lending.adapter.out.persistence.LoanJpaEntity;
import com.example.lending.adapter.out.persistence.LoanJpaRepository;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CreditCheckIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Autowired
    LoanJpaRepository loanJpaRepository;

    @Test
    void blocked_member_is_rejected_with_409_and_book_stays_loanable() throws Exception {
        String bookId = registerBook("신용 거절 책");
        String blockedMemberId = registerMember("BLOCKED-kim");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, blockedMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("CREDIT_REJECTED"));

        String otherMemberId = registerMember("정상 회원");
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, otherMemberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void approved_loan_returns_credit_check_result_on_get() throws Exception {
        String bookId = registerBook("신용 승인 책");
        String memberId = registerMember("승인 회원");

        String created = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanJson(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String loanId = objectMapper.readTree(created).get("loanId").asText();

        mockMvc.perform(get("/loans/" + loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.bookId").value(bookId))
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.creditCheck.approved").value(true))
                .andExpect(jsonPath("$.creditCheck.score").value(742))
                .andExpect(jsonPath("$.creditCheck.checkedAt").isNotEmpty());

        // 분쟁 대응을 위해 응답에 없는 근거 값도 대출 기록과 함께 남아 있어야 한다
        LoanJpaEntity saved = loanJpaRepository.findById(UUID.fromString(loanId)).orElseThrow();
        assertNotNull(saved.getCreditCheck());
        assertEquals("OK", saved.getCreditCheck().getReasonCodes());
        assertEquals("ExampleCredit", saved.getCreditCheck().getProviderName());
        assertEquals("2.3", saved.getCreditCheck().getProviderVersion());
    }

    @Test
    void getting_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(get("/loans/" + UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode member = objectMapper.readTree(registered);
        return member.get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String loanJson(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }
}

